// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address to, uint256 value) public {
        vm.assume(caller != address(0) && to != address(0));
        value = bound(value, 1, 1 ether);

        vm.deal(caller, value);
        vm.prank(caller);
        c.deposit{value: value}();

        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("migrateTo(address)", to));
        assertTrue(success == false, "migrateTo should revert for non-creator caller");
    }
}

